import { EChartsType } from '@/src/echarts';
import { createChart, getECModel } from '@/test/ut/core/utHelper';
import PieSeriesModel, { PieSeriesOption } from '@/src/chart/pie/PieSeries';
import { Sector } from '@/src/util/graphic';

interface LabelProbe {
    midAngle: number;
    rotation: number;
}

function layoutPieLabels(
    chart: EChartsType,
    rotate: PieSeriesOption['label']['rotate']
): LabelProbe[] {
    chart.setOption({
        animation: false,
        series: [{
            type: 'pie',
            radius: [40, 120],
            startAngle: 90,
            label: {
                show: true,
                position: 'inner',
                rotate: rotate,
                formatter: '{b}'
            },
            data: [
                { name: 'A', value: 1 },
                { name: 'B', value: 1 },
                { name: 'C', value: 1 },
                { name: 'D', value: 1 }
            ]
        }]
    }, true);

    const seriesModel = getECModel(chart).getSeriesByIndex(0) as PieSeriesModel;
    const data = seriesModel.getData();
    const probes: LabelProbe[] = [];
    for (let idx = 0; idx < data.count(); idx++) {
        const sector = data.getItemGraphicEl(idx) as Sector;
        const label = sector.getTextContent();
        probes.push({
            midAngle: (sector.shape.startAngle + sector.shape.endAngle) / 2,
            rotation: label.rotation
        });
    }
    return probes;
}

describe('pie_label_rotate', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart({ width: 400, height: 400 });
    });
    afterEach(function () {
        chart.dispose();
    });

    it('tangential flips the label on the lower half', function () {
        const probes = layoutPieLabels(chart, 'tangential');
        expect(probes.length).toBe(4);
        const flow = probes.map(p => Math.round(Math.sin(p.rotation + p.midAngle)));
        // Upper half (1:30 and 10:30) and lower half (4:30 and 7:30) read in
        // opposite tangential directions.
        expect(flow).toEqual([-1, 1, 1, -1]);
    });

    it('tangential-noflip keeps one tangential direction all around', function () {
        const probes = layoutPieLabels(chart, 'tangential-noflip' as any);
        expect(probes.length).toBe(4);
        probes.forEach(p => {
            // cos(rotation + midAngle) === 0 <=> the baseline is tangential.
            expect(Math.cos(p.rotation + p.midAngle)).toBeCloseTo(0, 6);
            // Always the same tangential direction, i.e. never flipped.
            expect(Math.sin(p.rotation + p.midAngle)).toBeCloseTo(-1, 6);
        });
    });

    it('tangential-noflip only differs from tangential on the flipped half', function () {
        const tangential = layoutPieLabels(chart, 'tangential');
        const noflip = layoutPieLabels(chart, 'tangential-noflip' as any);
        for (let i = 0; i < tangential.length; i++) {
            const isFlippedByTangential = Math.sin(tangential[i].midAngle) > 0;
            const delta = Math.cos(tangential[i].rotation - noflip[i].rotation);
            expect(delta).toBeCloseTo(isFlippedByTangential ? -1 : 1, 6);
        }
    });
});
